10	function cidrContains(cidr: string, ip: string): boolean {
11	  const [base, bits] = cidr.split("/");
12	  const mask = Number(bits) === 0 ? 0 : ~((1 << (32 - Number(bits))) - 1) >>> 0;
13	  return (toInt(base) & mask) === (toInt(ip) & mask);
14	}
